import { getAllProducts } from '@/lib/db';
import { revalidateTag, unstable_cacheTag as cacheTag } from 'next/cache';

interface Product {
  id: number;
  name: string;
  price: number;
}

async function CachedProductList() {
  'use cache';
  cacheTag('products');

  const products: Product[] = await getAllProducts();

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', marginBottom: '20px' }}>
      <h2 style={{ marginTop: 0 }}>Product List</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((p) => (
          <li key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '8px 0', borderBottom: '1px solid #eee' }}>
            <span>{p.name}</span>
            <span style={{ fontFamily: 'monospace' }}>${p.price}</span>
          </li>
        ))}
      </ul>
      <p style={{ fontSize: '0.8em', color: '#666' }}>
        Last fetched: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

async function invalidateProducts() {
  'use server';
  revalidateTag('products');
}

export default function Page() {
  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '40px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ marginBottom: '24px' }}>Product Caching Demo</h1>

      <p style={{ marginBottom: '20px', lineHeight: '1.5' }}>
        The list below is cached using the <code>use cache</code> directive. 
        Submitting the form will invalidate the <code>"products"</code> tag, causing the data to be re-fetched on the next render.
      </p>

      <CachedProductList />

      <form action={invalidateProducts}>
        <button 
          type="submit"
          style={{ 
            padding: '10px 20px', 
            backgroundColor: '#0070f3', 
            color: 'white', 
            border: 'none', 
            borderRadius: '5px', 
            cursor: 'pointer',
            fontSize: '16px'
          }}
        >
          Invalidate "products" Cache
        </button>
      </form>
    </div>
  );
}

